#!/usr/bin/env node
/* scripts/inject-env.js — reads .env (repo root) and generates
 * js/env.generated.js, which config.js picks up via window.__DISHA_ENV__.
 *
 *   cp .env.example .env   # fill in values (never commit .env)
 *   node scripts/inject-env.js
 *
 * Zero dependencies. Safe to run on hosts without any keys — it just
 * writes what's there. The generated file is gitignored.
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const ENV_PATH = path.join(ROOT, '.env');
const OUT_PATH = path.join(ROOT, 'js', 'env.generated.js');

function parseEnv(text) {
  const out = {};
  for (const line of text.split('\n')) {
    const t = line.trim();
    if (!t || t.startsWith('#')) continue;
    const i = t.indexOf('=');
    if (i === -1) continue;
    const k = t.slice(0, i).trim();
    let v = t.slice(i + 1).trim();
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) {
      v = v.slice(1, -1);
    }
    out[k] = v;
  }
  return out;
}

let env = {};
if (fs.existsSync(ENV_PATH)) {
  env = parseEnv(fs.readFileSync(ENV_PATH, 'utf8'));
} else {
  console.log('.env not found — writing empty config (keyless mode).');
}

const body =
  '// GENERATED by scripts/inject-env.js — do not edit. Regenerate after changing .env.\n' +
  '// This file is gitignored; it never leaves your machine unless you deploy it.\n' +
  'window.__DISHA_ENV__ = ' + JSON.stringify(env, null, 2) + ';\n';

fs.writeFileSync(OUT_PATH, body);
console.log('wrote js/env.generated.js with keys:', Object.keys(env).join(', ') || '(none)');
